head('4. 渲染：变量树进得去，转义出不来');

ok(H.valueHtml(['a', '<b>']).indexOf('&lt;b&gt;') >= 0, '数组项也会转义');
ok(H.valueHtml(['a']).indexOf('hud-tag') >= 0, '数组渲染成标签');
