/* ============================================================================
 * 骨架 HUD · 样式
 *
 * 规矩一条：所有选择器都带 .hud / .hud- 前缀。
 * 这段 CSS 会整段注进宿主的消息里，前缀就是它和宿主页面之间的边界 ——
 * 漏一个裸选择器（比如 body / .message），宿主的界面就会跟着变形。
 *
 * 另有一条：**这一页里不写死颜色。** 所有颜色、圆角、字体都从下面那组
 * `--hud-*` 槽里取，槽的默认值就是「羊皮卷」。
 * 要换皮肤就跑 `forge theme <主题名> <工程>` —— 它写一份 hud/主题.css，
 * 只覆盖这组槽，这一页一个字都不用改。这样换皮肤和改机制是两件事，
 * 改了一处也不会顺手把另一处弄坏。
 * ========================================================================== */

.hud,
.hud-ball,
.hud-ballpanel {
  /* ---- 文字三层 ---- */
  --hud-ink: #2f2a22;          /* 正文 */
  --hud-ink-2: #6b6152;        /* 次级：栏名、小节标题 */
  --hud-dim: #a2988a;          /* 更淡：说明、空态 */

  /* ---- 底色四层（从最透到最实）---- */
  --hud-paper: rgba(252, 248, 238, 0.72);   /* 卡片常态 */
  --hud-paper-solid: rgba(252, 248, 238, 0.9); /* 建卡器：要填字，底子实一点 */
  --hud-field: rgba(255, 253, 246, 0.9);    /* 输入框 / 扣子 */
  --hud-panel: rgba(252, 248, 238, 0.97);   /* 悬浮球面板：压在宿主任意背景上 */

  /* ---- 线两层 ---- */
  --hud-line: rgba(120, 94, 52, 0.28);      /* 常态分隔线 */
  --hud-line-2: rgba(120, 94, 52, 0.5);     /* 强调：主扣子边、悬浮球边 */

  /* ---- 淡底两块 ---- */
  --hud-wash: rgba(120, 94, 52, 0.08);      /* 标签 / 注释块 / hover */
  --hud-wash-2: rgba(120, 94, 52, 0.2);     /* 选中的标签 / 主扣子 */

  /* ---- 强调与警示 ---- */
  --hud-accent: rgba(120, 94, 52, 0.62);    /* 焦点边 */
  --hud-danger: #a8442f;                    /* 错误线 */
  --hud-danger-ink: #7d3324;                /* 错误字 */
  --hud-danger-wash: rgba(168, 68, 47, 0.09);

  /* ---- 形状 ---- */
  --hud-shadow: rgba(40, 32, 18, 0.2);
  --hud-radius: 4px;
  --hud-radius-s: 3px;
  --hud-font: -apple-system, "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;

  box-sizing: border-box;
}

/* ------------------------------------------------------------------ 卡片 */

.hud {
  margin: 10px 0;
  padding: 12px 14px 13px;
  border: 1px solid var(--hud-line);
  border-radius: var(--hud-radius);
  background: var(--hud-paper);
  color: var(--hud-ink);
  font: 13.5px/1.75 var(--hud-font);
}

.hud * {
  box-sizing: border-box;
}

/* ------------------------------------------------------------------ 表头 */

.hud-wrap {
  box-sizing: border-box;
  color: var(--hud-ink);
  font: 13.5px/1.75 var(--hud-font);
}

.hud-wrap__lead {
  margin: 0 0 8px;
  color: var(--hud-ink-2);
  font-size: 12.5px;
}

.hud__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--hud-line);
}

.hud__title {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.16em;
}

.hud__brief {
  margin-right: auto;
  color: var(--hud-ink-2);
  font-size: 12px;
}

.hud__body {
  margin-top: 9px;
}

.hud.is-fold .hud__body {
  display: none;
}

.hud__note {
  margin-top: 9px;
  padding: 6px 9px;
  border-left: 2px solid var(--hud-line);
  background: var(--hud-wash);
  font-size: 12px;
  line-height: 1.65;
  border-radius: 0 var(--hud-radius-s) var(--hud-radius-s) 0;
}

.hud__note.is-error {
  border-left-color: var(--hud-danger);
  background: var(--hud-danger-wash);
  color: var(--hud-danger-ink);
}

/* ------------------------------------------------------------------ 小节 */

.hud-sec + .hud-sec {
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px dashed var(--hud-line);
}

.hud-sec__h {
  margin-bottom: 4px;
  color: var(--hud-ink-2);
  font-size: 11.5px;
  letter-spacing: 0.14em;
}

.hud-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 1px 0;
}

.hud-row__k {
  flex: 0 0 4.6em;
  color: var(--hud-ink-2);
  font-size: 12px;
}

.hud-row__v {
  flex: 1 1 auto;
  min-width: 0;
  word-break: break-word;
}

.hud-sub {
  margin: 4px 0 4px 4px;
  padding-left: 9px;
  border-left: 1px solid var(--hud-line);
}

.hud-sub--deep {
  margin-left: 2px;
  opacity: 0.92;
}

.hud-sub__t {
  color: var(--hud-ink-2);
  font-size: 11.5px;
  letter-spacing: 0.1em;
}

.hud-tag {
  display: inline-block;
  margin: 1px 4px 1px 0;
  padding: 1px 6px;
  border: 1px solid var(--hud-line);
  border-radius: 2px;
  background: var(--hud-wash);
  font-size: 12px;
}

.hud-tag.is-on {
  border-color: var(--hud-line-2);
  background: var(--hud-wash-2);
}

.hud-dim {
  color: var(--hud-dim);
  font-size: 12px;
}

.hud-empty {
  padding: 6px 0;
  color: var(--hud-dim);
  font-size: 12px;
}

/* ---------------------------------------------------------------- 建卡器 */

.hud--create {
  background: var(--hud-paper-solid);
}

.hud__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(148px, 1fr));
  gap: 8px 10px;
  margin-top: 10px;
}

.hud-field {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.hud-field--wide {
  grid-column: 1 / -1;
}

.hud-field__l {
  color: var(--hud-ink-2);
  font-size: 11.5px;
  letter-spacing: 0.1em;
}

.hud-input {
  width: 100%;
  padding: 5px 7px;
  border: 1px solid var(--hud-line);
  border-radius: var(--hud-radius-s);
  background: var(--hud-field);
  color: var(--hud-ink);
  font: inherit;
  font-size: 13px;
}

.hud-input:focus {
  outline: none;
  border-color: var(--hud-accent);
  background: var(--hud-field);
}

.hud-input--area {
  resize: vertical;
  min-height: 58px;
  font-size: 12.5px;
  line-height: 1.6;
}

.hud__row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 10px;
}

.hud__foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
  margin-top: 11px;
  padding-top: 10px;
  border-top: 1px solid var(--hud-line);
}

/* ------------------------------------------------------------------ 扣子 */

.hud-btn {
  padding: 6px 12px;
  border: 1px solid var(--hud-line);
  border-radius: var(--hud-radius-s);
  background: var(--hud-field);
  color: var(--hud-ink);
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
}

.hud-btn:hover {
  background: var(--hud-wash);
}

.hud-btn--main {
  border-color: var(--hud-line-2);
  background: var(--hud-wash-2);
  font-weight: 700;
  letter-spacing: 0.08em;
}

/* 次要动作压成灰底小字：留着能用，但不跟主扣子抢视线 */
.hud-btn--quiet {
  padding: 4px 8px;
  border-color: var(--hud-line);
  color: var(--hud-ink-2);
  font-size: 11.5px;
}

/* ---------------------------------------------------------------- 悬浮球 */

.hud-ball {
  position: fixed;
  z-index: 2147483000;
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--hud-line-2);
  border-radius: 50%;
  background: var(--hud-panel);
  color: var(--hud-ink);
  font: 700 15px/1 var(--hud-font);
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
  box-shadow: 0 2px 10px var(--hud-shadow);
}

.hud-ball:active {
  cursor: grabbing;
}

.hud-ballpanel {
  position: fixed;
  z-index: 2147482999;
  width: 258px;
  max-height: 62vh;
  overflow: auto;
  padding: 10px 12px 12px;
  border: 1px solid var(--hud-line-2);
  border-radius: var(--hud-radius);
  background: var(--hud-panel);
  color: var(--hud-ink);
  font: 12.5px/1.7 var(--hud-font);
  box-shadow: 0 6px 22px var(--hud-shadow);
}

.hud-ballpanel__t {
  margin-bottom: 6px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--hud-line);
  color: var(--hud-ink-2);
  font-size: 11.5px;
  letter-spacing: 0.16em;
}

.hud-ballpanel .hud-sec__h {
  margin-top: 8px;
}

@media (prefers-reduced-motion: reduce) {
  .hud-ball,
  .hud-ballpanel {
    transition: none;
  }
}

