/* ------------------------------------------------------------------ 小节 */

.hud-sec + .hud-sec {
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px dashed var(--hud-line);
}

.hud-sec__h {
  margin-bottom: 4px;
  color: var(--hud-ink-2);
  font-size: 11.5px;
  letter-spacing: 0.14em;
}

.hud-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 1px 0;
}

.hud-row__k {
  flex: 0 0 4.6em;
  color: var(--hud-ink-2);
  font-size: 12px;
}

.hud-row__v {
  flex: 1 1 auto;
  min-width: 0;
  word-break: break-word;
}

.hud-sub {
  margin: 4px 0 4px 4px;
  padding-left: 9px;
  border-left: 1px solid var(--hud-line);
}

.hud-sub--deep {
  margin-left: 2px;
  opacity: 0.92;
}

.hud-sub__t {
  color: var(--hud-ink-2);
  font-size: 11.5px;
