  background: var(--hud-wash-2);
}

.hud-dim {
  color: var(--hud-dim);
  font-size: 12px;
}

.hud-empty {
  padding: 6px 0;
  color: var(--hud-dim);
  font-size: 12px;
}

/* ---------------------------------------------------------------- 建卡器 */

.hud--create {
  background: var(--hud-paper-solid);
}

.hud__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(148px, 1fr));
  gap: 8px 10px;
  margin-top: 10px;
}

.hud-field {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.hud-field--wide {
  grid-column: 1 / -1;
}

.hud-field__l {
  color: var(--hud-ink-2);
  font-size: 11.5px;
  letter-spacing: 0.1em;
}

.hud-input {
  width: 100%;
  padding: 5px 7px;
  border: 1px solid var(--hud-line);
  border-radius: var(--hud-radius-s);
  background: var(--hud-field);
  color: var(--hud-ink);
  font: inherit;
  font-size: 13px;
}

.hud-input:focus {
