  border-color: var(--hud-accent);
  background: var(--hud-field);
}

.hud-input--area {
  resize: vertical;
  min-height: 58px;
  font-size: 12.5px;
  line-height: 1.6;
}

.hud__row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 10px;
}

.hud__foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
  margin-top: 11px;
  padding-top: 10px;
  border-top: 1px solid var(--hud-line);
